/** Runs every step in order. Each call owns its output and drift state. */
export async function runFlow(page: Page, vars: Vars, options: RunOptions = {}): Promise<Outputs> {
  validateInputs(vars);
  page.setDefaultTimeout(30000);
  page.setDefaultNavigationTimeout(30000);
  const run = options.run ?? createFlowRun();
  run.outputs = {};
  run.drift.length = 0;
  run.echoed = [];
  run.referenceOnly = [];
  run.created = [];
  run.warnings = [];
  const outputs = run.outputs;
  try {
    const browserMismatch = profileMismatch(RECORDED_BROWSER, await readLiveBrowser(page));
    if (browserMismatch) {
      run.warnings.push(browserMismatch);
      console.log(`[sitelooper warn] ${browserMismatch}`);
    }
    // Traffic is recorded from the start url on, as the daemon records it from adopting the page.
    pageTraffic(page);
    await page.goto(options.startUrl ?? 'http://127.0.0.1:8096/', { waitUntil: 'load', timeout: GOTO_TIMEOUT_MS });
    await waitForContent(page).catch(() => {});
    await startPageSettled(page).catch(() => {});
    await test.step('01-signin: Sign in to Vikunja with username \'admin\' and password \'{{env:APP_PASSWORD}}\' (type the password text exactly as given, it will be filled in automatically). After signing in, report which page you land on and whether login succeeded.', async () => {
      await steps['01-signin'](page, { v1: 'admin', v2: process.env['APP_PASSWORD'] ?? '' }, outputs, run);
      console.log('[sitelooper step] 01-signin');
    });
    await test.step('02-open: Open the project named \'{{01-signin.visible_projects_2}}\' from the sidebar and list the titles of all tasks in it whose title starts with \'Seed:\', exactly as displayed. Do not modify anything. Report the exact titles.', async () => {
      await steps['02-open'](page, { v1: need(outputs, '01-signin.visible_projects_2', '02-open') }, outputs, run);
      console.log('[sitelooper step] 02-open');
    });
    await test.step('03-create: In the \'{{01-signin.visible_projects_2}}\' project, create a new task with the exact title \'{{runid}} Bench Task\' and a description that includes the text \'{{runid}}\' (e.g. \'Bench task created for run {{runid}}\'). Fill in the title and description in the task creation form and submit/save it. Then open the newly created task\'s own detail page and report its title, its description text, and the identifier the app displays for it (Vikunja shows something like BENCH-<number>). Do not touch the tasks whose titles start with \'Seed:\'.', async () => {
      await steps['03-create'](page, { v1: need(outputs, '01-signin.visible_projects_2', '03-create'), v2: vars.runid, v3: `${vars.runid} Bench Task`, v4: `Bench task created for run ${vars.runid}` }, outputs, run);
      console.log('[sitelooper step] 03-create');
    });
    await test.step('04-set: On the task detail page for the task titled \'{{runid}} Bench Task\' (identifier {{03-create.task_identifier}}, url {{03-create.url}}), set the due date to 2026-12-31 (December 31, 2026) and set the priority to \'High\'. These fields edit in place and save automatically when changed or when you click away — there is no Save button for the whole page. After setting both, verify on the page that the due date shows 2026-12-31 and the priority shows High, and report exactly what the page displays for each.', async () => {
      await steps['04-set'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: outputs['03-create.task_identifier'] ?? '', v4: outputs['03-create.url'] ?? '', v5: 'December' }, outputs, run);
      console.log('[sitelooper step] 04-set');
    });
    await test.step('05-add: On the task detail page for the task titled \'{{runid}} Bench Task\' (identifier {{03-create.task_identifier}}, url {{03-create.url}}), add the EXISTING label named \'Backend\' to the task. Important: the label field creates a NEW label from whatever text is typed unless an existing label is chosen from its suggestions — so type \'Backend\' and then select the existing \'Backend\' label from the suggestion dropdown that appears (do NOT just press Enter to create a new one). Verify afterwards that the task shows the label \'Backend\' and report exactly what label(s) are displayed on the task page. Do not modify anything else.', async () => {
      await steps['05-add'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: outputs['03-create.task_identifier'] ?? '', v4: outputs['03-create.url'] ?? '' }, outputs, run);
      console.log('[sitelooper step] 05-add');
    });
    await test.step('06-add: On the task detail page for the task titled \'{{runid}} Bench Task\' (identifier {{03-create.task_identifier}}, url {{03-create.url}}), add a comment whose text includes \'{{runid}}\' (e.g. \'Comment for run {{runid}}\'). Find the comment box, type the text, and submit/save the comment. Then verify the comment appears on the task page and report the exact comment text displayed and who posted it.', async () => {
      await steps['06-add'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: outputs['03-create.task_identifier'] ?? '', v4: outputs['03-create.url'] ?? '', v5: `Comment for run ${vars.runid}` }, outputs, run);
      console.log('[sitelooper step] 06-add');
    });
    await test.step('07-open: Open the task detail page at {{03-create.url}} (task titled \'{{runid}} Bench Task\') and read-only verify all of the following, reporting the exact text shown on the page for each: (a) the task title, (b) the task identifier shown on the page (like BENCH-<number>), (c) the description text, (d) the due date, (e) the priority, (f) the label(s) attached, (g) the comment text and its author. Do not change anything.', async () => {
      await steps['07-open'](page, { v1: outputs['03-create.url'] ?? '', v2: `${vars.runid} Bench Task`, v3: vars.runid }, outputs, run);
      console.log('[sitelooper step] 07-open');
    });
    await test.step('08-open: Open the \'{{01-signin.visible_projects_2}}\' project list view (read-only) and report the exact titles of all tasks listed, in order, confirming the three \'Seed:\' tasks are present and unmodified, and that \'{{runid}} Bench Task\' is also listed. Do not change anything.', async () => {
      await steps['08-open'](page, { v1: need(outputs, '01-signin.visible_projects_2', '08-open'), v2: `${vars.runid} Bench Task`, v3: vars.runid }, outputs, run);
      console.log('[sitelooper step] 08-open');
    });
    return outputs;
  } finally {
    DRIFT.splice(0, DRIFT.length, ...run.drift);
  }
}
